async function syncOrders(db:any,b:any){const status='ACTIVE',pp=Math.min(500,Math.max(1,Number(b.per_page||500))),mp=Math.min(10,Math.max(1,Number(b.max_pages||4))),map=await staffMap(db);let seen=0,created=0,updated=0,pages=0;for(let page=1;page<=mp;page++){const q=new URLSearchParams({page:String(page),per_page:String(pp),status});if(b.date_from)q.set('date_from',clean(b.date_from));if(b.date_to)q.set('date_to',clean(b.date_to));if(b.search)q.set('search',clean(b.search));const rows=listFromResponse(await hands(`/orders/?${q}`));pages++;if(!rows.length)break;for(const o of rows){const r=await importOrder(db,o,map);if(r.ok){seen++;r.created?created++:updated++}}if(rows.length<pp)break}return{seen,created,updated,pages,status}}
